int last_beacon(int ids[], int n) {
    return ids[n - 1];
}

int last_beacon(int ids[], int n) {
    int last = ids[0];
    int i = 1;
    while (i < n) {
        last = ids[i];
        i++;
    }
    return last;
}

int last_beacon(int ids[], int n) {
    int last = 0;
    for (int i = 0; i < n; i++) {
        last = ids[i];
    }
    return last;
}
